// Package postgres is progress's Repo on the platform database (queries.sql, generated by sqlc).
package postgres

import (
	"context"
	"database/sql"
	"errors"
	"time"

	"github.com/IhebBelhadj/opsforge-academy/academy/internal/progress"
)

// Repo implements progress.Repo.
type Repo struct {
	q *Queries
}

var _ progress.Repo = (*Repo)(nil)

// NewRepo uses the open database db.
func NewRepo(db *sql.DB) *Repo { return &Repo{q: New(db)} }

// Records are user's records in a course, by item id.
func (r *Repo) Records(ctx context.Context, user int64, course string) (map[string]progress.Record, error) {
	rows, err := r.q.ItemRecords(ctx, ItemRecordsParams{UserID: user, CourseID: course})
	if err != nil {
		return nil, err
	}
	out := make(map[string]progress.Record, len(rows))
	for _, row := range rows {
		out[row.ItemID] = progress.Record{Hash: row.ContentHash.String, CompletedAt: optTime(row.CompletedAt),
			OpenedAt: optTime(row.LastOpenedAt)}
	}
	return out, nil
}

// Complete records a lecture's completion on content hash.
func (r *Repo) Complete(ctx context.Context, user int64, course, item, hash string, at time.Time) error {
	return r.q.CompleteItem(ctx, CompleteItemParams{UserID: user, CourseID: course, ItemID: item,
		ContentHash: sql.NullString{String: hash, Valid: true}, CompletedAt: sql.NullTime{Time: at, Valid: true}})
}

// Open records that the item was opened at `at`.
func (r *Repo) Open(ctx context.Context, user int64, course, item string, at time.Time) error {
	return r.q.OpenItem(ctx, OpenItemParams{UserID: user, CourseID: course, ItemID: item, LastOpenedAt: sql.NullTime{Time: at, Valid: true}})
}

// CompleteCourse records a course's first completion; false if it was already recorded.
func (r *Repo) CompleteCourse(ctx context.Context, user int64, course string, at time.Time) (bool, error) {
	n, err := r.q.InsertCourseCompletion(ctx, InsertCourseCompletionParams{UserID: user, CourseID: course,
		CompletedAt: at})
	return n == 1, err
}

// CourseCompletions are user's first completions, by course id.
func (r *Repo) CourseCompletions(ctx context.Context, user int64) (map[string]time.Time, error) {
	rows, err := r.q.CourseCompletions(ctx, user)
	if err != nil {
		return nil, err
	}
	out := make(map[string]time.Time, len(rows))
	for _, row := range rows {
		out[row.CourseID] = row.CompletedAt
	}
	return out, nil
}

// Note is user's note on an item (empty when there is none).
func (r *Repo) Note(ctx context.Context, user int64, course, item string) (progress.Note, error) {
	row, err := r.q.GetNote(ctx, GetNoteParams{UserID: user, CourseID: course, ItemID: item})
	if errors.Is(err, sql.ErrNoRows) {
		return progress.Note{}, nil
	}
	if err != nil {
		return progress.Note{}, err
	}
	return progress.Note{Body: row.Body, UpdatedAt: &row.UpdatedAt}, nil
}

// SaveNote replaces user's note on an item.
func (r *Repo) SaveNote(ctx context.Context, user int64, course, item string, n progress.Note) error {
	var at time.Time
	if n.UpdatedAt != nil {
		at = *n.UpdatedAt
	}
	return r.q.SaveNote(ctx, SaveNoteParams{UserID: user, CourseID: course, ItemID: item, Body: n.Body,
		UpdatedAt: at})
}

func optTime(t sql.NullTime) *time.Time {
	if !t.Valid {
		return nil
	}
	return &t.Time
}
